            } else if (c4.capacity === 'triage') {
                cost += C.TRIAGE_COST;
                triaged = C.TRIAGE_FP * hNew;
                hNew = hNew - triaged;
                fr += C.TRIAGE_FR * triaged;
            } else {
                outCases = C.OUT_CASES;
            }
            if (c4.kpi === 'volume') { s = C.S_VOLUME; }
        }
        var need = hNew + fNew;
        var dh = hNew + backH;
        var df = fNew + backF;
        var dem = dh + df;
        var capTot = capEff + outCases;
        var k, vs, cs, ratio;
        if (dem <= capTot || dem <= 0) {
            k = dem;
            vs = 1.0;
            cs = 1.0;
        } else {
            k = capTot;
            ratio = k / dem;
            vs = Math.pow(ratio, C.ALPHA[r1.order]);
            cs = Math.pow(ratio, C.BETA[r1.order]);
        }
        var tpInv = df * cs;
        if (tpInv > k) { tpInv = k; }
        var honInv = k - tpInv;
        var outShare = 0.0;
        if (outCases > 0 && k > 0) {
            outShare = Math.max(0.0, k - capEff) / k;
            if (outShare > 0) { cost += C.OUT_COST * (k - capEff); }
        }
        var sEff = (outShare > 0 && s === C.S_OK) ? s * (1.0 - outShare) + C.S_OUT * outShare : s;
        prevented = sEff * vs * df * C.FV + lowPrev;
        fr += C.FR_INV[pol] * honInv + C.OUT_FR * honInv * outShare;
        if (t === 4 && dec.round4.kpi === 'savings') {
            var kw = C.KPI_WRONG * honInv;
            fr += C.WRONG * kw;
        }
        var unresH = dh - honInv;
        var unresF = df - tpInv;
        var unresFv = (1.0 - vs) * df * C.FV;
        var carryH = 0.0;
        var carryF = 0.0;
        var up = r2.unres;
        if (unresH + unresF > 1e-9) {
            if (up === 'deny') {
                wrong = unresH;
                prevented += unresFv;
                fr += C.WRONG * wrong;
            } else if (up === 'extend' && t < 4) {
                carryH = unresH;
                carryF = unresF;
                fr += C.FR_WAIT[pol] * unresH;
            } else {
                fr += C.FR_UNRES[pol] * unresH;
            }
        }
        var ringLoss = 0.0;
        var ringRec = 0.0;
        if (t >= 3) {
            var rg = dec.round3.ring;
            if (rg === 'quiet') {
                ringLoss = C.RING_Q;
            } else if (rg === 'network') {
                ringLoss = (t === 3) ? C.RING_Q * 0.5 : 0.0;
                ringRec = (t === 4) ? C.RING_RECOVER : 0.0;
            } else if (t === 3) {
                var bw = C.RING_CLAIMS * C.RING_HONEST;
                wrong += bw;
                fr += C.WRONG * bw;
            }
        }
        if (t === 3) { cost += C.DETER_COST[dec.round3.deter]; }
        if (t === 4 && dec.round3.deter === 'inspect') {
            var ins = C.INSPECT_SHARE * C.N;
            cost += C.INSPECT_COST * ins;
            fr += C.INSPECT_FR * ins;
        }
        var deterred = C.N * (C.F0 - prevalence(dec, t)) * C.FV;
        var nv = prevented + deterred + ringRec - ringLoss - cost - fr;
        return {
            t: t, need: need, deterred: deterred, alerts: aTot, demand: dem, cap: capTot, inv: k, prec: prec,
            prevented: prevented, friction: fr, cost: cost, wrong: wrong,
            honAffected: dh + triaged + (pol === 'fast' ? C.LOW_SHARE * aTot * (1.0 - prec) : 0.0),
            nv: nv, carryH: carryH, carryF: carryF, ringLoss: ringLoss, ringRec: ringRec, thr: thr,
            fraudRate: prevalence(dec, t), backlog: carryH + carryF
        };
    }

    function sizeRank(dec, t, chosen) {
        var gaps = [];
        var i, q;
        for (i = 0; i < THR.length; i++) {
            q = quarter(dec, t, 0.0, 0.0, THR[i]);
            gaps.push({ g: Math.abs(q.need - q.cap) / q.cap, i: i, thr: THR[i] });
        }
        gaps.sort(function(a, b) { return (a.g - b.g) || (a.i - b.i); });
        var order = gaps.map(function(x) { return x.thr; });
        return { pts: C.SIZE_PTS[order.indexOf(chosen)], best: order[0] };
    }

    class FraudeRedAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Fraude en la Red';
            this.version = '1.0.0';
            this.ROUNDS = [
                { panel: 'roundPanel1', nameKey: 'r1_name', briefKey: 'r1_brief' },
                { panel: 'roundPanel2', nameKey: 'r2_name', briefKey: 'r2_brief' },
                { panel: 'roundPanel3', nameKey: 'r3_name', briefKey: 'r3_brief' },
                { panel: 'roundPanel4', nameKey: 'r4_name', briefKey: 'r4_brief' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    quarters: [],
                    wrongCum: 0,
                    capFlag: false,
                    dec: {},
                    scoreHistory: [],
                    performance: { overallScore: 0 },
                    performanceTier: 'beginner'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }

        _syncControlsFromDecisions(state) {
            var raw = (state && state.decisions) || {};
            var saved = (state && state.domainState && state.domainState.dec) || {};
            var d = {
                round1: raw.round1 || saved.round1,
                round2: raw.round2 || saved.round2,
                round3: raw.round3 || saved.round3,
                round4: raw.round4 || saved.round4
            };
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) { el.value = String(val); }
            };
            if (d.round1) { set('r1_tool', d.round1.tool); set('r1_threshold', d.round1.threshold); set('r1_order', d.round1.order); }
            if (d.round2) { set('r2_honest', d.round2.honest); set('r2_unres', d.round2.unres); set('r2_feedback', d.round2.feedback); }
            if (d.round3) { set('r3_ring', d.round3.ring); set('r3_deter', d.round3.deter); set('r3_measure', d.round3.measure); }
            if (d.round4) { set('r4_capacity', d.round4.capacity); set('r4_kpi', d.round4.kpi); set('r4_threshold', d.round4.threshold); }
        }

        _t(key, vars) {
            return window.mySimulation ? window.mySimulation.t(key, vars) : key;
        }

        _cl(key, fallback) {
            var s = this._t(key);
            return s === key ? fallback : s;
        }

        _lang() {
            return (window.mySimulation && window.mySimulation.language === 'en') ? 'en' : 'es';
        }

        _fmtNum(v, dec) {
            var n = Number(v) || 0;
            var neg = n < 0;
            var f = Math.abs(n).toFixed(dec);
            var parts = f.split('.');
            var s = parts[0];
            var out = '';
            var th = this._lang() === 'en' ? ',' : '.';
            var dp = this._lang() === 'en' ? '.' : ',';
            while (s.length > 3) { out = th + s.slice(-3) + out; s = s.slice(0, -3); }
            out = s + out;
            if (parts.length > 1) { out = out + dp + parts[1]; }
            return (neg && Number(f) !== 0 ? '−' : '') + out;
        }

        _fmtMoney(v) {
            var n = Math.round(Number(v) || 0);
            var body = this._fmtNum(Math.abs(n), 0);
            if (this._lang() === 'en') { return (n < 0 ? '−€' : '€') + body; }
            return (n < 0 ? '−' : '') + body + ' €';
        }

        _fmtPct(v) {
            var x = this._fmtNum((Number(v) || 0) * 100, 1);
            return this._lang() === 'en' ? x + '%' : x + ' %';
        }

        _updateBriefing(state) {
            var cur = (state && state.currentPeriod) || 1;
            var maxP = (state && state.maxPeriods) || this.ROUNDS.length;
            var done = (state && state.history) ? state.history.length : 0;
            var finished = done >= maxP || cur > this.ROUNDS.length;
            var i, panel;
            for (i = 0; i < this.ROUNDS.length; i++) {
                panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var qs = ds.quarters || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('semesterText');
            if (sEl) { sEl.innerHTML = qs.length ? this._quarterHtml(ds, qs[qs.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ea2173-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ea2173-warn'); }
                }
            }
        }

        _quarterHtml(ds, q) {
            var v = {
                alerts: this._fmtNum(q.alerts, 0), prec: this._fmtPct(q.prec), cap: this._fmtNum(q.cap, 0),
                inv: this._fmtNum(q.inv, 0), backlog: this._fmtNum(q.backlog, 0),
                prev: this._fmtMoney(q.prevented), cost: this._fmtMoney(q.cost), fr: this._fmtMoney(q.friction), nv: this._fmtMoney(q.nv)
            };
            var html = this._t('sem_body', v);
            html += '<span class="ea2173-cases">' + this._t('s_money', v) + '</span>';
            html += '<span class="ea2173-cases">' + this._t('s_committee', v) + '</span>';
            if (q.t >= 3) { html += '<span class="ea2173-cases">' + this._t('s_ring', { loss: this._fmtMoney(q.ringLoss), rec: this._fmtMoney(q.ringRec) }) + '</span>'; }
            if (q.t === 4 && q.sample) {
                html += '<span class="ea2173-reveal">' + this._t('s_deter_seen', { rate: this._fmtPct(q.fraudRate), det: this._fmtMoney(q.deterred) }) + '</span>';
            } else if (q.t === 4) {
                html += '<span class="ea2173-reveal">' + this._t('s_deter_unseen') + '</span>';
            }
            if (q.wrong > 0) { html += '<span class="ea2173-reveal">' + this._t('s_wrong', { w: this._fmtNum(q.wrong, 0) }) + '</span>'; }
            var keys = ds.capKeys || [];
            var i;
            for (i = 0; i < keys.length; i++) { html += '<span class="ea2173-reveal">' + this._t(keys[i]) + '</span>'; }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: this._fmtNum(Math.round(r.pts * 10) / 10, 1) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var tool = this._readSelect('r1_tool', CTRL.round1.tool);
                var threshold = this._readSelect('r1_threshold', CTRL.round1.threshold);
                var order = this._readSelect('r1_order', CTRL.round1.order);
                if (!tool || !threshold || !order) { return warn('warn_r1'); }
                decisions.round1 = { tool: tool, threshold: threshold, order: order };
                return true;
            }
            if (period === 2) {
                var honest = this._readSelect('r2_honest', CTRL.round2.honest);
                var unres = this._readSelect('r2_unres', CTRL.round2.unres);
                var feedback = this._readSelect('r2_feedback', CTRL.round2.feedback);
                if (!honest || !unres || !feedback) { return warn('warn_r2'); }
                decisions.round2 = { honest: honest, unres: unres, feedback: feedback };
                return true;
            }
            if (period === 3) {
                var ring = this._readSelect('r3_ring', CTRL.round3.ring);
                var deter = this._readSelect('r3_deter', CTRL.round3.deter);
                var measure = this._readSelect('r3_measure', CTRL.round3.measure);
                if (!ring || !deter || !measure) { return warn('warn_r3'); }
                decisions.round3 = { ring: ring, deter: deter, measure: measure };
                return true;
            }
            if (period === 4) {
                var capacity = this._readSelect('r4_capacity', CTRL.round4.capacity);
                var kpi = this._readSelect('r4_kpi', CTRL.round4.kpi);
                var threshold4 = this._readSelect('r4_threshold', CTRL.round4.threshold);
                if (!capacity || !kpi || !threshold4) { return warn('warn_r4'); }
                decisions.round4 = { capacity: capacity, kpi: kpi, threshold: threshold4 };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every carried quantity, the backlog above all, is rebuilt from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var quarters = [];
            var total = 0.0;
            var backH = 0.0;
            var backF = 0.0;
            var wcum = 0.0;
            var denyflag = false;
            var cap = 100.0;
            var r, known, q, rub, outp, pts, best4;
            for (r = 1; r <= period; r++) {
                known = this._known(d, r);
                q = quarter(known, r, backH, backF, null);
                backH = q.carryH;
                backF = q.carryF;
                wcum += q.wrong;
                if (r >= 2 && known.round2.unres === 'deny') { denyflag = true; }
                if (r >= 3 && known.round3.ring === 'block') { denyflag = true; }
                best4 = null;
                if (r === 4) { best4 = sizeRank(known, 4, known.round4.threshold).best; }
                rub = this._rubric(known, r);
                outp = 10.0 * clamp((q.nv - C.NV_LO) / (C.NV_HI[r - 1] - C.NV_LO), 0.0, 1.0);
                pts = rub + outp;
                total += pts;
                cap = denyflag ? Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAP_W * wcum) : 100.0;
                q.sample = (r >= 3 && known.round3.measure === 'sample');
                quarters.push(q);
                rounds.push({ period: r, rub: rub, outp: outp, pts: pts, verdictKey: this._verdict(known, r, best4) });
            }
            ds.rounds = rounds;
            ds.quarters = quarters;
            ds.wrongCum = wcum;
            ds.capFlag = denyflag;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (cap < 100 && total > cap) { ds.capKeys.push('cap_refuse'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            var last = quarters[quarters.length - 1];
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                alerts: Math.round(last.alerts),
                prec: Math.round(last.prec * 1000) / 10,
                prevented: Math.round(last.prevented),
                honest: Math.round(last.honAffected),
                nv: Math.round(last.nv),
                score: score,
                overallScore: score
            };
        }

        _known(d, r) {
            var out = {};
            var k;
            for (k = 1; k <= r; k++) { if (d['round' + k]) { out['round' + k] = d['round' + k]; } }
            return out;
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d;
            if (r === 1) {
                d = dec.round1;
                return P.tool1[d.tool] + sizeRank(dec, 1, d.threshold).pts + P.order1[d.order];
            }
            if (r === 2) {
                d = dec.round2;
                return P.honest2[d.honest] + P.unres2[d.unres] + P.feedback2[d.feedback];
            }
            if (r === 3) {
                d = dec.round3;
                return P.ring3[d.ring] + P.deter3[d.deter] + P.measure3[d.measure];
            }
            d = dec.round4;
            return P.capacity4[d.capacity] + P.kpi4[d.kpi] + sizeRank(dec, 4, d.threshold).pts;
        }

        _verdict(dec, r, best4) {
            var d;
            if (r === 1) {
                d = dec.round1;
                var best = sizeRank(dec, 1, d.threshold).best;
                if (d.tool === 'rules' && d.threshold === 'wide') { return 'flood'; }
                if (d.threshold !== best) { return 'size'; }
                if (d.order === 'fifo') { return 'fifo'; }
                if (d.tool === 'rules') { return 'rules'; }
                if (d.order === 'amount') { return 'amount'; }
                return 'ok';
            }
            if (r === 2) {
                d = dec.round2;
                if (d.unres === 'deny') { return 'deny'; }
                if (d.honest === 'freeze') { return 'freeze'; }
                if (d.unres === 'extend') { return 'extend'; }
                if (d.feedback !== 'all') { return 'feedback'; }
                if (d.honest === 'fast') { return 'fast'; }
                return 'ok';
            }
            if (r === 3) {
                d = dec.round3;
                if (d.ring === 'block') { return 'block'; }
                if (d.ring === 'quiet') { return 'quiet'; }
                if (d.deter === 'inspect') { return 'inspect'; }
                if (d.measure === 'savings') { return 'savings'; }
                if (d.deter === 'none') { return 'nodeter'; }
                if (d.measure === 'confirmed') { return 'confirmed'; }
                return 'ok';
            }
            d = dec.round4;
            if (d.kpi === 'savings') { return 'bonus'; }
            if (d.threshold !== best4) { return 'size'; }
            if (d.kpi === 'volume') { return 'volume'; }
            if (d.capacity !== 'triage') { return 'capacity'; }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        setupUI(uiManager) {
            var self = this;
            var lastQ = function(ds) { var qs = (ds && ds.quarters) || []; return qs.length ? qs[qs.length - 1] : null; };
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('alertsDisplay', 'domainState', function(ds) { var q = lastQ(ds); return q ? self._fmtNum(q.alerts, 0) : '—'; });
            uiManager.bind('precDisplay', 'domainState', function(ds) { var q = lastQ(ds); return q ? self._fmtPct(q.prec) : '—'; });
            uiManager.bind('prevDisplay', 'domainState', function(ds) { var q = lastQ(ds); return q ? self._fmtMoney(q.prevented) : '—'; });
            uiManager.bind('honestDisplay', 'domainState', function(ds) { var q = lastQ(ds); return q ? self._fmtNum(q.honAffected, 0) : '—'; });
            uiManager.bind('netDisplay', 'domainState', function(ds) { var q = lastQ(ds); return q ? self._fmtMoney(q.nv) : '—'; });
            uiManager.bind('backlogDisplay', 'domainState', function(ds) { var q = lastQ(ds); return q ? self._fmtNum(q.backlog, 0) : '0'; });
        }

        getChartConfig() {
