        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundPoints', label: 'Points', i18nKey: 'col_points' },
                { key: 'results.alerts', label: 'Alerts', i18nKey: 'col_alerts', formatter: function(v) { return self._fmtNum(v, 0); } },
                { key: 'results.prec', label: 'Precision', i18nKey: 'col_prec', formatter: function(v) { return self._fmtPct((Number(v) || 0) / 100); } },
