        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var qs = ds.quarters || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var net = 0.0, prev = 0.0, hon = 0.0, fric = 0.0;
            var i;
            for (i = 0; i < qs.length; i++) { net += qs[i].nv; prev += qs[i].prevented; hon += qs[i].honAffected; fric += qs[i].friction; }
            var last = qs.length ? qs[qs.length - 1] : null;
            var dec = ds.dec || {};
            var sample = !!(dec.round3 && dec.round3.measure === 'sample');
            var deterOk = sample && dec.round3 && dec.round3.deter === 'warning';
            var insights = [];
            insights.push((last && last.prec >= 0.45) ? this._t('insight_prec_ok') : this._t('insight_prec_bad'));
            insights.push((ds.wrongCum || 0) > 0 ? this._t('insight_refuse_bad') : this._t('insight_refuse_ok'));
            insights.push(deterOk ? this._t('insight_deter_ok') : this._t('insight_deter_bad'));
            insights.push(fric <= 300000 ? this._t('insight_friction_ok') : this._t('insight_friction_bad'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                net: net,
                prevented: prev,
                honest: hon,
                wrong: ds.wrongCum || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ea2173-cm">'
                + '<div class="ea2173-cm-score">' + score + '<span class="ea2173-cm-max">/100</span></div>'
                + '<div class="ea2173-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="ea2173-cm-kpis">'
                + '<div class="ea2173-cm-kpi">' + this._t('cm_kpi_net') + '<strong>' + this._fmtMoney(s.net) + '</strong></div>'
                + '<div class="ea2173-cm-kpi">' + this._t('cm_kpi_prev') + '<strong>' + this._fmtMoney(s.prevented) + '</strong></div>'
                + '<div class="ea2173-cm-kpi">' + this._t('cm_kpi_honest') + '<strong>' + this._fmtNum(s.honest, 0) + '</strong></div>'
                + '<div class="ea2173-cm-kpi">' + this._t('cm_kpi_wrong') + '<strong>' + this._fmtNum(s.wrong, 0) + '</strong></div>'
                + '</div>'
                + '<div class="ea2173-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ea2173-cm-insights">' + items + '</ul>'
                + '</div>';
        }

